// --zimm-scale equivalent exists at either pixel pair.
// audit-allow: Figma-confirmed cart-item image dimensions, no foundation token at this value.
const IMAGE_WIDTH_MOBILE = '67px';
const IMAGE_WIDTH_DESKTOP = '132px';

// Figma "colour + size" caption string: 200px, no --zimm-scale equivalent at this value.
// audit-allow: Figma-confirmed width, no foundation token at this value.
const COLOUR_SIZE_WIDTH = '200px';

/**
 * Recipe key — single source of truth, imported by item-image.tsx/item-attributes.tsx/
 * item-price.tsx instead of each redeclaring the same string literal (SFCC-270 round 2 rework).
 */
export const ZIMM_CART_ITEM_VARIANT_RECIPE = 'ZimmCartItemVariant';

/**
 * Co-located recipe for the item-variant family (item-image / item-attributes / item-price).
 * SFCC-270 (plan step 2.2).
 *
 * Parts:
 *   - `image` — item-image.tsx's outer Box: responsive width, ivory-200 background. Applied
 *     via `__css`, not `sx` — this one MUST stay overridable: order-summary/index.jsx (base
 *     SFCC, not yet overridden in this repo) calls
 *     `<CartItemVariantImage width="80px" mr={2} />` and depends on its own caller-supplied
 *     `width` winning over whatever default this component ships. `__css` is the lowest-
 *     priority slot in `@chakra-ui/system`'s `toCSSObject` merge (`chunk-E32MZNBA.mjs`:
 *     `assignAfter({}, __css, baseStyle, styleProps, sx)`), and `Box` carries no competing
 *     baseStyle of its own (`@chakra-ui/layout`'s `chunk-6CSUKJP7.mjs`: `var Box =
 *     chakra("div")`, no options) — confirmed by reading both files, not assumed — so a
 *     literal caller prop always wins over this part's `__css` default.
 *   - `img` — the inner <Image>: responsive objectFit (contain mobile / cover desktop) plus
 *     mix-blend-multiply, so the photo blends against the `image` part's ivory backdrop.
 *     `__css` is safe here too — Chakra's own `Image` (`@chakra-ui/image`'s
 *     `chunk-SMHKDLMK.mjs`) never sets a literal `__css` key of its own, unlike `Text` below.
 *   - `colourSize` — item-attributes.tsx's combined "colour, size" string.
 *   - `price` — item-price.tsx's price Stack (`textStyle: 'price'` only; the actual price
 *     digits render via the base, un-overridden `display-price`/`current-price` components,
 *     which set no competing font-size of their own — confirmed by reading both files — so
 *     the textStyle cascades down via ordinary CSS inheritance without touching either file).
 *
 * `colourSize` and `price` are applied via `sx`, not `__css`: Chakra's own `Text`
 * (`@chakra-ui/layout`'s `chunk-P74GIWPW.mjs`) places its OWN `__css={styles}` (from
 * `useStyleConfig('Text', props)`) as a literal key AFTER `...rest` in its own render call —
 * a caller-supplied `__css` prop would be silently discarded entirely there (a later
 * same-named key in one object literal replaces the earlier one; it does not merge). `sx` is
 * destructured separately by `toCSSObject` and isn't subject to that collision, so it's the
 * reliable way to style a plain `<Text>`/`<Stack>` from outside. Verified by reading the
 * compiled source directly. `price`'s own Stack has no such hazard (`@chakra-ui/layout`'s
 * `chunk-WKZT7ZXJ.mjs` Stack sets no literal `__css` key at all), so either mechanism would
 * have worked there — `sx` is used anyway, for one consistent rule across this file's parts
 * rather than a different mechanism per element.
 */
export const ZimmCartItemVariant = {
  parts: ['image', 'img', 'colourSize', 'price'],
  baseStyle: {
    image: {
      width: IMAGE_WIDTH_MOBILE,
      backgroundColor: 'var(--zimm-color-bg-02)',
      [`@media (min-width: ${breakpoints.md})`]: {
        width: IMAGE_WIDTH_DESKTOP,
      },
    },
    img: {
      objectFit: 'contain',
      mixBlendMode: 'multiply',
      [`@media (min-width: ${breakpoints.md})`]: {
        objectFit: 'cover',
      },
    },
    colourSize: {
      textStyle: 'caption',
      // No fontWeight override here (round 2 rework — corrects the prior round's backwards
      // reasoning). Figma's colour+size string is the MEDIUM-weight "Default/Caption-strong"
      // node, not the regular-weight "Default/Caption" node — .claude/session-notes.md says so
      // twice, independently, both dated 2026-09-16 and headed RESOLVED: §11.2 ("colour + size:
      // ONE combined string ... `Default/Caption-strong` 12px / lh18") and §11.10(5) ("no
      // `captionStrong` for Figma's `Default/Caption-strong` (the cart item's colour+size line,
      // medium/500) — we only have `caption`"). This repo's `caption` textStyle
      // (theme/foundation/typography.ts) is already medium-weight (`fontWeight:
      // fontWeights.medium`), i.e. it already matches Default/Caption-strong, so `textStyle:
      // 'caption'` alone gives the correct weight with nothing to override.
      width: COLOUR_SIZE_WIDTH,
      color: 'var(--zimm-color-text-secondary)',
    },
    price: {
      textStyle: 'price',
    },
  },
};

  // checks, without inventing a fallback value the base file never had.
  basePrice: number;
};

const PricePerItem = ({ currency, basePrice }: PricePerItemProps) => {
  return (
    <Text fontSize={{ base: '12px', lg: '14px' }}>
      <FormattedNumber style="currency" currency={currency} value={basePrice} />
      <FormattedMessage
        defaultMessage="ea"
        id="price_per_item.label.each"
        description="Abbreviated 'each', follows price per item, like $10/ea"
      />
    </Text>
  );
